                        sq = wasm_i32x4_add(sq, wasm_i32x4_dot_i16x8(wasm_i16x8_add(lo, hi), ones));
                        sq2 = wasm_i32x4_add(sq2, wasm_i32x4_add(wasm_i32x4_dot_i16x8(lo, lo), wasm_i32x4_dot_i16x8(hi, hi)));
